[
  {
    "version": "v0.9",
    "createSurface": {
      "surfaceId": "sunscreen-recs",
      "catalogId": "https://genui.local/specification/v0_9/standard_catalog.json"
    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "sunscreen-recs",
      "components": [
        {
          "id": "root",
          "type": "Column",
          "properties": {
            "children": [
              {
                "id": "main_tabs",
                "type": "Tabs",
                "properties": {
                  "tabs": [
                    {
                      "label": "Mineral Sunscreens",
                      "childId": "sunscreens_tab_content"
                    },
                    {
                      "label": "Verification & Assumptions",
                      "childId": "info_tab_content"
                    }
                  ]
                }
              },
              {
                "id": "actions_divider",
                "type": "Divider"
              },
              {
                "id": "actions_title",
                "type": "Text",
                "properties": {
                  "value": "Quick Actions",
                  "style": "title"
                }
              },
              {
                "id": "actions_row",
                "type": "Row",
                "properties": {
                  "horizontalArrangement": "spaceEvenly",
                  "children": [
                    {
                      "id": "pipette_button",
                      "type": "Button",
                      "properties": {
                        "label": "Learn More at Pipette",
                        "action": {
                          "type": "functionCall",
                          "call": "openUrl",
                          "arguments": {
                            "url": "https://www.pipettebaby.com/products/mineral-sunscreen-spf-50"
                          }
                        }
                      }
                    },
                    {
                      "id": "thinksport_button",
                      "type": "Button",
                      "properties": {
                        "label": "Learn More at Thinksport",
                        "action": {
                          "type": "functionCall",
                          "call": "openUrl",
                          "arguments": {
                            "url": "https://gothink.com/products/thinksport-sunscreen-spf-50"
                          }
                        }
                      }
                    },
                    {
                      "id": "badger_button",
                      "type": "Button",
                      "properties": {
                        "label": "Learn More at Badger",
                        "action": {
                          "type": "functionCall",
                          "call": "openUrl",
                          "arguments": {
                            "url": "https://www.badgerbalm.com/products/sport-sunscreen-tin-spf-50"
                          }
                        }
                      }
                    }
                  ]
                }
              },
              {
                "id": "sources_divider",
                "type": "Divider"
              },
              {
                "id": "sources_title",
                "type": "Text",
                "properties": {
                  "value": "Sources",
                  "style": "title"
                }
              },
              {
                "id": "sources_text",
                "type": "Text",
                "properties": {
                  "value": "- [Environmental Working Group (EWG) Sunscreen Guide](https://www.ewg.org/sunscreen/)"
                }
              }
            ]
          }
        },
        {
          "id": "sunscreens_tab_content",
          "type": "Column",
          "properties": {
            "children": [
              {
                "id": "sunscreens_intro",
                "type": "Text",
                "properties": {
                  "value": "Here are three highly-regarded, fragrance-free mineral sunscreens featuring non-nano zinc oxide that are suitable for sensitive skin."
                }
              },
              {
                "id": "pipette_card",
                "type": "Card",
                "properties": {
                  "child": {
                    "id": "pipette_row",
                    "type": "Row",
                    "properties": {
                      "verticalAlignment": "center",
                      "children": [
                        {
                          "id": "pipette_image",
                          "type": "Image",
                          "properties": {
                            "source": "/Gj3H6xL.png",
                            "alt": "Pipette Mineral Sunscreen SPF 50",
                            "width": "100px"
                          }
                        },
                        {
                          "id": "pipette_details",
                          "type": "Column",
                          "properties": {
                            "children": [
                              {
                                "id": "pipette_title",
                                "type": "Text",
                                "properties": {
                                  "value": "Option 1: Pipette Mineral Sunscreen SPF 50",
                                  "style": "title"
                                }
                              },
                              {
                                "id": "pipette_desc",
                                "type": "Text",
                                "properties": {
                                  "value": "A lightweight, moisturizing formula that blends easily without leaving a heavy white cast, making it excellent for daily use on face and body."
                                }
                              },
                              {
                                "id": "pipette_specs",
                                "type": "Text",
                                "properties": {
                                  "value": "**Primary Active Ingredient**: Non-Nano Zinc Oxide (20%)\n**Typical Container Size**: 4 fl oz"
                                }
                              }
                            ]
                          }
                        }
                      ]
                    }
                  }
                }
              },
              {
                "id": "thinksport_card",
                "type": "Card",
                "properties": {
                  "child": {
                    "id": "thinksport_row",
                    "type": "Row",
                    "properties": {
                      "verticalAlignment": "center",
                      "children": [
                        {
                          "id": "thinksport_image",
                          "type": "Image",
                          "properties": {
                            "source": "/a5o0f1Q.png",
                            "alt": "Thinksport SPF 50+ Mineral Sunscreen",
                            "width": "100px"
                          }
                        },
                        {
                          "id": "thinksport_details",
                          "type": "Column",
                          "properties": {
                            "children": [
                              {
                                "id": "thinksport_title",
                                "type": "Text",
                                "properties": {
                                  "value": "Option 2: Thinksport SPF 50+ Mineral Sunscreen",
                                  "style": "title"
                                }
                              },
                              {
                                "id": "thinksport_desc",
                                "type": "Text",
                                "properties": {
                                  "value": "A popular and trusted option known for its high water resistance and clean ingredient list. It's a top-rated choice for both adults and children with active lifestyles."
                                }
                              },
                              {
                                "id": "thinksport_specs",
                                "type": "Text",
                                "properties": {
                                  "value": "**Primary Active Ingredient**: Non-Nano Zinc Oxide (20%)\n**Typical Container Size**: 3 fl oz"
                                }
                              }
                            ]
                          }
                        }
                      ]
                    }
                  }
                }
              },
              {
                "id": "badger_card",
                "type": "Card",
                "properties": {
                  "child": {
                    "id": "badger_row",
                    "type": "Row",
                    "properties": {
                      "verticalAlignment": "center",
                      "children": [
                        {
                          "id": "badger_image",
                          "type": "Image",
                          "properties": {
                            "source": "/h5r88oE.png",
                            "alt": "Badger Sport Mineral Sunscreen Cream SPF 50",
                            "width": "100px"
                          }
                        },
                        {
                          "id": "badger_details",
                          "type": "Column",
                          "properties": {
                            "children": [
                              {
                                "id": "badger_title",
                                "type": "Text",
                                "properties": {
                                  "value": "Option 3: Badger Sport Mineral Sunscreen Cream SPF 50",
                                  "style": "title"
                                }
                              },
                              {
                                "id": "badger_desc",
                                "type": "Text",
                                "properties": {
                                  "value": "This sunscreen features a simple, concentrated formula with very few ingredients, making it an excellent choice for extremely sensitive or reactive skin. It is very water resistant but has a thicker consistency."
                                }
                              },
                              {
                                "id": "badger_specs",
                                "type": "Text",
                                "properties": {
                                  "value": "**Primary Active Ingredient**: Non-Nano Zinc Oxide (25%)\n**Typical Container Size**: 2.9 fl oz"
                                }
                              }
                            ]
                          }
                        }
                      ]
                    }
                  }
                }
              }
            ]
          }
        },
        {
          "id": "info_tab_content",
          "type": "Column",
          "properties": {
            "children": [
              {
                "id": "assumptions_title",
                "type": "Text",
                "properties": {
                  "value": "Assumptions",
                  "style": "title"
                }
              },
              {
                "id": "assumptions_text",
                "type": "Text",
                "properties": {
                  "value": "\"Highly-rated\" is based on consistently positive consumer and editorial reviews for effectiveness and gentleness on sensitive skin. Product formulations and sizes are based on information available as of 2023."
                }
              },
              {
                "id": "verification_title",
                "type": "Text",
                "properties": {
                  "value": "Verification Framework",
                  "style": "title"
                }
              },
              {
                "id": "verification_text",
                "type": "Text",
                "properties": {
                  "value": "Product formulations, availability, and packaging can change. Before purchasing, it is always best to verify the most current information.\n\n1. Check the brand's official website for the latest ingredient list and specifications.\n2. Read recent customer reviews on major retail websites (e.g., Target, Amazon, Sephora) for feedback on the current formula.\n3. Consult resources like the Environmental Working Group (EWG) Sunscreen Guide for updated safety and efficacy ratings."
                }
              }
            ]
          }
        }
      ]
    }
  }
]
